# Let's manually identify patterns from the changed pairs

inputs = ['vwxbda', 'bdge', 'fbdzy', 'zac', 'ee']
outputs = ['vwxbddci', 'bdgf', 'fbdxy', 'xdcic', 'xdci']

# Find changed pairs manually
changed_pairs = []
for i in range(len(inputs)):
    if inputs[i] != outputs[i]:
        changed_pairs.append((i, inputs[i], outputs[i]))

print("Changed pairs:", changed_pairs)

# Analyze each change
for idx, inp, outp in changed_pairs:
    print(f"\nPair {idx}: '{inp}' -> '{outp}'")

    # Find minimal edit
    # Simple approach: look for substring differences
    if len(inp) == len(outp):
        # Same length, check character by character
        for j in range(len(inp)):
            if inp[j] != outp[j]:
                print(f"  Position {j}: '{inp[j]}' -> '{outp[j]}'")
    else:
        # Different lengths - need to find substitution
        # We can check if one string is a substring of another
        print(f"  Length change: {len(inp)} -> {len(outp)}")

        # Look for common substrings
        if len(outp) > len(inp):
            # Insertion case
            for i in range(len(inp) + 1):
                if i < len(outp) and outp[:i] == inp[:i] and outp[i+1:] == inp[i:]:
                    print(f"  Insert '{outp[i]}' at position {i}")
        elif len(outp) < len(inp):
            # Deletion case
            for i in range(len(inp)):
                if inp[:i] == outp[:i] and inp[i+1:] == outp[i:]:
                    print(f"  Delete '{inp[i]}' at position {i}")

